const aiDisclosurePatterns = [
  /^\s*(?:#{1,6}\s*)?(?:AI|IA)(?:\s+(?:disclosure|assistance|usage))?\s*$/im,
  /\b(?:used|using|assisted by|assisted with|generated by|generated with|written by|written with|authored by|authored with)\s+(?:GitHub\s+)?(?:Copilot|Claude(?: Code)?|Cursor|Amp|ChatGPT|(?:OpenAI\s+)?Codex|Gemini|Windsurf|Cline|Aider|OpenCode|Devin|Zed)\b/i,
  /\b(?:Copilot|Claude(?: Code)?|Cursor|Amp|ChatGPT|(?:OpenAI\s+)?Codex|Gemini|Windsurf|Cline|Aider|OpenCode|Devin|Zed)\s+(?:was\s+)?(?:used|assisted|generated|wrote|authored)\b/i,
  /\b(?:AI|IA)[- ](?:tool|usage|assisted|generated)\s*(?:[:=-]\s*|with\s+)(?:GitHub\s+)?(?:Copilot|Claude(?: Code)?|Cursor|Amp|ChatGPT|(?:OpenAI\s+)?Codex|Gemini|Windsurf|Cline|Aider|OpenCode|Devin|Zed)\b/i,
  /\b(?:model|llm)\s*:\s*(?:GPT(?:-\d+(?:\.\d+)?)?|Opus|Sonnet|Haiku|Claude|Gemini|GLM|Llama|DeepSeek|Qwen|Mistral)\b/i,
];

const visualProofPattern =
  /!\[[^\]]*\]\([^)]+\)|<img\b[^>]*>|<(?:video|source)\b[^>]*>|https?:\/\/\S+\.(?:png|jpe?g|gif|webp|mp4|mov|webm)(?:\?\S*)?|https?:\/\/github\.com\/user-attachments\/(?:assets|files)\//i;

function hasAiDisclosure(content) {
  return aiDisclosurePatterns.some(pattern => pattern.test(content));
}

function hasVisualProof(content) {
  return visualProofPattern.test(content);
}

async function run(github, context, core) {
  const { owner, repo } = context.repo;
  const pullNumber = context.payload.pull_request.number;
  const pullRequestBody = context.payload.pull_request.body ?? '';
  const commits = await github.paginate(github.rest.pulls.listCommits, {
    owner,
    repo,
    pull_number: pullNumber,
    per_page: 100,
  });
  const content = [pullRequestBody, ...commits.map(({ commit }) => commit.message)].join('\n');

  if (!hasVisualProof(pullRequestBody)) {
    const marker = '<!-- lila-ai-policy-visual-proof -->';
    const comments = await github.paginate(github.rest.issues.listComments, {
      owner,
      repo,
      issue_number: pullNumber,
      per_page: 100,
    });

    if (!comments.some(({ body }) => body?.includes(marker))) {
      await github.rest.issues.createComment({
        owner,
        repo,
        issue_number: pullNumber,
        body: `${marker}\nPlease add visual proof of your manual testing to the pull request description (a screenshot or, ideally, a video), as requested by [AI_POLICY.md](https://github.com/lichess-org/lila/blob/master/AI_POLICY.md).`,
      });
    }
  }

  if (hasAiDisclosure(content)) {
    await github.rest.issues.addLabels({
      owner,
      repo,
      issue_number: pullNumber,
      labels: ['AI'],
    });

    try {
      await github.request('POST /repos/{owner}/{repo}/pulls/{pull_number}/copilot-code-review', {
        owner,
        repo,
        pull_number: pullNumber,
        headers: { 'X-GitHub-Api-Version': '2026-03-10' },
      });
    } catch (error) {
      if (error.status === 409) {
        core.info('A Copilot code review is already pending.');
      } else {
        throw error;
      }
    }
  }
}

module.exports = { hasAiDisclosure, hasVisualProof, run };
